# area: descriptors_properties
# hypothesis: A passthrough decorator on __get__, __set__ and __delete__ keeps their declared types, so assigning a str to an int-typed descriptor is an arg-type error that checkers report while CPython accepts it at runtime.
from typing import reveal_type


def passthrough[F](fn: F) -> F:
    return fn


class Clamp:
    def __init__(self) -> None:
        self.value = 0

    @passthrough
    def __get__(self, obj: object, owner: type | None = None) -> int:
        return self.value

    @passthrough
    def __set__(self, obj: object, value: int) -> None:
        self.value = value

    @passthrough
    def __delete__(self, obj: object) -> None:
        self.value = 0


class Host:
    level = Clamp()


h = Host()
h.level = 5
reveal_type(h.level)
print(h.level)
h.level = 'high'  # expect-error
print(h.level)
del h.level
print(h.level)
